import sys
sys.path.insert(0, ".")
from dates import parse_date
cases = {"2024-1-5": (2024, 1, 5), "1999-9-9": (1999, 9, 9), "2024-12-5": (2024, 12, 5),
         "2024-1-15": (2024, 1, 15), "2023-2-28": (2023, 2, 28), "2000-01-7": (2000, 1, 7), "2000-7-01": (2000, 7, 1)}
