import sys
sys.path.insert(0, ".")
from dates import parse_date
for s, exp in {"2024-01-05": (2024, 1, 5), "1999-12-31": (1999, 12, 31), "2000-02-29": (2000, 2, 29),
               "2023-10-10": (2023, 10, 10), "1970-01-01": (1970, 1, 1)}.items():
    r = parse_date(s)
    if r != exp or not isinstance(r, tuple) or not all(type(x) is int for x in r):
        sys.exit(1)
for bad in ["", "abc", "2024/01/05", "2024-01", "2024-01-05x", "x2024-01-05", "20240105"]:
    try:
        parse_date(bad)
    except ValueError:
        continue
    sys.exit(1)
sys.exit(0)
